def f(g):
    h=len(g); w=len(g[0]); bg=g[0][0]
    o=[[bg]*w for _ in range(h)]
    from collections import defaultdict
    cells=defaultdict(list)
    for y in range(h):
        for x in range(w):
            if g[y][x]!=bg: cells[g[y][x]].append((y,x))
    # objects: 4-connected components of non-bg colors
    used=set()
    objs=[]
    for c,cs in list(cells.items()):
        for (y,x) in cs:
            if (y,x) not in used:
                st=[(y,x)]; comp=[]
                while st:
                    yy,xx=st.pop()
                    if (yy,xx) in used: continue
                    used.add((yy,xx)); comp.append((yy,xx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=yy+dy,xx+dx
                        if 0<=a<h and 0<=b<w and g[a][b]==g[y][x] and (a,b) not in used:
                            st.append((a,b))
                objs.append((c,comp))
    for c,cs in objs:
        b=bbox(cs); H=b[2]-b[0]+1; W=b[3]-b[1]+1
        for i,y in enumerate(range(b[0],b[2]+1)):
            for j,x in enumerate(range(b[1],b[3]+1)):
                if g[y][x]==c and (i in (0,H-1) or j in (0,W-1)) and g[y][x-1]==c and g[y-1][x]==c:
                    pass
        # fill interior holes with 8 if fully enclosed (all 4 neighbors same color)
        for y,x in cs:
            inner=True
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                a,b=y+dy,x+dx
                if 0<=a<h and 0<=b<w and g[a][b]==c: inner=False
            if inner: o[y][x]=8
    return o
