def fill(g):
    h=len(g); w=len(g[0]); bg=g[0][0]
    o=[row[:] for row in g]
    for y in range(h):
        for x in range(w):
            if g[y][x]==bg:
                nb=sum(1 for dy in (-1,0,1) for dx in (-1,0,1) if (dy or dx) and 0<=y+dy<h and 0<=x+dx<w and g[y+dy][x+dx]!=bg)
                if nb==8: o[y][x]=8
    return o
